enum Msg {
    Effect(Vec<Note>),
    Tune(Option<&'static [Note]>),
}

static FAT: AtomicBool = AtomicBool::new(false);
static CUR_HZ: AtomicU32 = AtomicU32::new(0); // frequency of the tune note playing now (0 = rest / none)
static POS: AtomicUsize = AtomicUsize::new(0); // index of the tune note playing now

/// Frequency of the song note playing right now (0 = silence); used by the music visualiser.
pub fn cur_hz() -> u32 { CUR_HZ.load(Ordering::Relaxed) }
/// Index of the song note playing right now.
pub fn song_pos() -> usize { POS.load(Ordering::Relaxed) }
static ACTIVE: AtomicBool = AtomicBool::new(false); // a background tune / song is playing
static ONCE: AtomicBool = AtomicBool::new(false); // the current tune plays once (songs) instead of looping

#[derive(Clone)]
pub struct Sound {
    tx: Sender<Msg>,
    pub enabled: Arc<AtomicBool>,
    pub status: Arc<Mutex<String>>,
}

impl Sound {
    /// A silent Sound that has no thread and never touches the BIO (safe mode).
    pub fn disabled() -> Sound {
        let (tx, _rx) = channel();
        Sound {
            tx,
            enabled: Arc::new(AtomicBool::new(false)),
            status: Arc::new(Mutex::new(String::from("off (safe mode)"))),
        }
    }

    pub fn start() -> Sound {
        let (tx, rx) = channel();
        let enabled = Arc::new(AtomicBool::new(true));
        let status = Arc::new(Mutex::new(String::from("starting")));
        let st = status.clone();
        let en = enabled.clone();
        std::thread::Builder::new().name("sound".into()).spawn(move || run(rx, en, st)).ok();
        Sound { tx, enabled, status }
    }

    /// Queue a sound effect (plays before the background tune continues).
    pub fn play(&self, notes: &[Note]) {
        if self.enabled.load(Ordering::Relaxed) {
            self.tx.send(Msg::Effect(notes.to_vec())).ok();
        }
    }

    /// Set (or clear) the looping background tune.
    pub fn tune(&self, t: Option<&'static [Note]>) {
        FAT.store(false, Ordering::Relaxed);
        ONCE.store(false, Ordering::Relaxed);
        ACTIVE.store(t.is_some(), Ordering::Relaxed);
        self.tx.send(Msg::Tune(t)).ok();
    }

    /// Like `tune`, but every note is played as a fast two-voice shimmer (note + octave) for a fuller buzzer sound.
    pub fn tune_fat(&self, t: Option<&'static [Note]>) {
        FAT.store(false, Ordering::Relaxed); // the two-voice shimmer is switched off: plain notes sound better
        ONCE.store(true, Ordering::Relaxed);
        ACTIVE.store(t.is_some(), Ordering::Relaxed);
        self.tx.send(Msg::Tune(t)).ok();
    }

    /// Stop the background tune (effects already queued still play).
    /// True while a background tune or song is still playing (a song that has finished is false).
    pub fn tune_active(&self) -> bool { ACTIVE.load(Ordering::Relaxed) }

    pub fn silence(&self) { self.tune(None); }

    pub fn toggle(&self) -> bool {
        let on = !self.enabled.load(Ordering::Relaxed);
        self.enabled.store(on, Ordering::Relaxed);
        if !on {
            self.tune(None);
        }
        on
    }

    pub fn status_text(&self) -> String { self.status.lock().map(|s| s.clone()).unwrap_or_default() }
}

// FIFO1 (x17) input: first two words = pin masks A and B, then pairs (half-period ticks, full periods) per note.
// The two pins are driven in opposite phase (bridge drive): a buzzer wired between them sees +-3.3 V instead of
// 0..3.3 V, which is about 4x the power = clearly louder. With B unused (mask 0) it is a normal one-pin tone.
// Both pins idle low while the core waits on the FIFO.
#[rustfmt::skip]
bio_code!(tone_kernel, TONE_START, TONE_END,
    "mv x4, x17",   // pin mask A
    "mv x5, x17",   // pin mask B (0 = not used)
    "or x6, x4, x5",
    "mv x26, x6",   // apply the combined mask to all GPIO operations
    "mv x24, x6",   // make both pins outputs
    "mv x21, x0",   // both low
"10:",
    "mv x8, x17",   // half period in ticks (blocks until the host sends it)
    "mv x9, x17",   // number of full periods
"20:",
    "mv x21, x4",   // A high, B low
    "mv x10, x8",
"21:",
    "mv x20, x0",   // wait one tick
    "addi x10, x10, -1",
    "bne x10, x0, 21b",
    "mv x21, x5",   // A low, B high
    "mv x10, x8",
"22:",
    "mv x20, x0",
    "addi x10, x10, -1",
    "bne x10, x0, 22b",
    "addi x9, x9, -1",
    "bne x9, x0, 20b",
    "mv x21, x0",   // both low (silence)
    "j 10b"
);

struct Tone {
    _bio: Bio,
    _handle: CoreHandle,
    tx: CoreCsr,
    bridge: bool,
}

fn init_tone() -> Result<Tone, String> {
    let mut bio = Bio::new();
    let spec = ResourceSpec {
        claimer: "ChocoTone".to_string(),
        cores: vec![CoreRequirement::Any],
        fifos: vec![Fifo::Fifo1],
        static_pins: vec![],
        dynamic_pin_count: 2,
    };
    let grant = bio.claim_resources(&spec).map_err(|e| format!("claim {:?}", e))?;
    let config = CoreConfig { clock_mode: ClockMode::TargetFreqInt(TICK_HZ) };
    bio.init_core(grant.cores[0], tone_kernel(), config).map_err(|e| format!("init {:?}", e))?;
    bio.set_core_run_state(&grant, true);
    bio.claim_dynamic_pin(BIO_PIN, &spec.claimer).map_err(|e| format!("pin {:?}", e))?;
    let mut mask_b = 0u32;
    let mut bridge = false;
    if bio.claim_dynamic_pin(BIO_PIN_B, &spec.claimer).is_ok() {
        mask_b = 1 << u5::new(BIO_PIN_B).as_u32();
        bridge = true;
    }
    let mask_a = 1u32 << u5::new(BIO_PIN).as_u32();
    let mut io = IoConfig::default();
    io.mapped = mask_a | mask_b;
    io.mode = IoConfigMode::SetOnly; // add our pins; never wipe the other core's mapping
    bio.setup_io_config(io).map_err(|e| format!("io {:?}", e))?;
    // safety: the handle is stored in the Tone object so it outlives the CSR view
    let handle = unsafe { bio.get_core_handle(Fifo::Fifo1) }
        .map_err(|e| format!("fifo {:?}", e))?
        .ok_or_else(|| "no FIFO1 handle".to_string())?;
    let mut tx = CoreCsr::from_handle(&handle);
    tx.csr.wo(bio_bdma::SFR_TXF1, mask_a);
    tx.csr.wo(bio_bdma::SFR_TXF1, mask_b);
    Ok(Tone { _bio: bio, _handle: handle, tx, bridge })
}

impl Tone {
    /// Start a note and return immediately (the core plays it by itself).
    fn start(&mut self, hz: u32, ms: u32) {
        let hz = if hz < 4000 { hz * 2 } else { hz }; // everything an octave higher: the buzzer is much louder there
        let half = (TICK_HZ / (2 * hz.clamp(50, 250_000))).max(1);
        let actual = TICK_HZ / (2 * half); // the frequency the core really makes (whole ticks), so lengths are exact
        let periods = (actual as u64 * ms as u64 / 1000).max(1) as u32;
        self.tx.csr.wo(bio_bdma::SFR_TXF1, half);
        self.tx.csr.wo(bio_bdma::SFR_TXF1, periods);
    }

    /// A silence of `ms`: the core plays 45 kHz, which a buzzer cannot reproduce. This lets us queue rests and gaps
    /// into the core like notes, so the timing no longer depends on when this thread wakes up.
    fn silence(&mut self, ms: u32) { self.start(45_000, ms.max(1)); }
}

fn run(rx: Receiver<Msg>, enabled: Arc<AtomicBool>, status: Arc<Mutex<String>>) {
    let tt = ticktimer::Ticktimer::new().unwrap();
    tt.sleep_ms(3500).ok(); // after the rest of the system has started
    let mut tone = match init_tone() {
        Ok(t) => {
            if let Ok(mut s) = status.lock() {
                *s = if t.bridge { "BIO tone ok (bridge)".into() } else { "BIO tone ok".into() };
            }
            Some(t)
        }
        Err(e) => {
            log::error!("sound: BIO tone init failed: {}", e);
            if let Ok(mut s) = status.lock() {
                *s = format!("BIO fail: {}", e);
            }
            None
        }
    };
    let mut effects: VecDeque<Note> = VecDeque::new();
    let mut tune: Option<&'static [Note]> = None;
    let mut idx = 0usize;
    let mut pending: Option<Note> = None;
    // The BIO core plays what we queue by itself, back to back. We keep up to three (frequency, length) pairs queued
    // ahead of the clock, so even if this thread is delayed by other work (drawing, USB) the music does not stutter.
    let mut ends: VecDeque<Instant> = VecDeque::new(); // when each queued pair finishes
    let mut busy_until = Instant::now();
    loop {
        // collect messages without blocking; block only when there is nothing to play at all
        loop {
            let now = Instant::now();
            while ends.front().map_or(false, |e| *e <= now) {
                ends.pop_front();
            }
            let idle = effects.is_empty() && tune.is_none() && pending.is_none() && busy_until <= now;
            let m = if idle {
                match rx.recv() {
                    Ok(m) => m,
                    Err(_) => return,
                }
            } else {
                match rx.try_recv() {
                    Ok(m) => m,
                    Err(TryRecvError::Empty) => break,
                    Err(TryRecvError::Disconnected) => return,
                }
            };
            match m {
                Msg::Effect(v) => effects.extend(v),
                Msg::Tune(t) => {
                    tune = t;
                    idx = 0;
                    pending = None;
                    CUR_HZ.store(0, Ordering::Relaxed);
                }
            }
        }
        let on = enabled.load(Ordering::Relaxed);
        // top up the core's queue
        loop {
            let now = Instant::now();
            while ends.front().map_or(false, |e| *e <= now) {
                ends.pop_front();
            }
            if ends.len() >= 2 {
                break; // one playing and one waiting is enough; never overfill the FIFO
            }
            let mut from_tune = false;
            let mut note: Option<Note> = None;
            if let Some(n) = effects.pop_front() {
                note = Some(n);
            } else if on {
                if let Some(p) = pending.take() {
                    if tune.is_some() {
                        note = Some(p);
                        from_tune = true;
                    }
                } else if let Some(t) = tune {
                    if ONCE.load(Ordering::Relaxed) && idx >= t.len() {
                        tune = None; // the song is over
                        ACTIVE.store(false, Ordering::Relaxed);
                        CUR_HZ.store(0, Ordering::Relaxed);
                        break;
                    }
                    let n = t[idx % t.len()];
                    POS.store(idx % t.len(), Ordering::Relaxed);
                    CUR_HZ.store(n.0 & !TIE, Ordering::Relaxed);
                    idx += 1;
                    note = Some(n);
                    from_tune = true;
                }
            }
            let Some((raw, ms)) = note else { break };
            let hz = raw & !TIE;
            let mut ms = ms;
            let mut tied = raw & TIE != 0; // a piece of a long note tied to the next: no gap
            // song notes go out in short slices, so a click or effect never waits long behind them
            if from_tune && ms > SLICE_MS + 15 {
                pending = Some((raw, ms - SLICE_MS));
                ms = SLICE_MS;
                tied = true;
            }
            let gap = if tied { 0 } else { 10 }; // a short silence so repeated notes stay distinct
            let start = if busy_until > now { busy_until } else { now };
            if hz != REST && on {
                if let Some(t) = tone.as_mut() {
                    t.start(hz, ms);
                    if gap > 0 {
                        t.silence(gap);
                    }
                    crate::diag::SND_BUSY_MS.fetch_add(ms, Ordering::Relaxed);
                }
            } else if let Some(t) = tone.as_mut() {
                if on {
                    t.silence(ms + gap);
                }
            }
            ends.push_back(start + Duration::from_millis(ms as u64));
            if gap > 0 {
                ends.push_back(start + Duration::from_millis((ms + gap) as u64));
            }
            busy_until = start + Duration::from_millis((ms + gap) as u64);
        }
        // wake up again when there is room for the next note (or in 15 ms to look for messages)
        let now = Instant::now();
        let wait = ends.front().map_or(15, |e| e.saturating_duration_since(now).as_millis() as u64).clamp(3, 15);
        if tune.is_some() && !on {
            tt.sleep_ms(100).ok();
        } else if !ends.is_empty() || !effects.is_empty() || pending.is_some() || tune.is_some() {
            tt.sleep_ms(wait as usize).ok();
        }
    }
}

const SLICE_MS: u32 = 40;
